package com.bank.factory;

import java.math.BigDecimal;
import java.util.logging.Logger;

interface PaymentMethod { void pay(BigDecimal amount); } // product interface

class UpiPayment implements PaymentMethod {
    public void pay(BigDecimal amount) { Logger.getLogger("PAY").info("UPI paid " + amount); }
}
class CardPayment implements PaymentMethod {
    public void pay(BigDecimal amount) { Logger.getLogger("PAY").info("Card paid " + amount); }
}

class PaymentFactory {
    static PaymentMethod create(String type) {       // single place to create
        return switch (type.toUpperCase()) {
            case "UPI"  -> new UpiPayment();
            case "CARD" -> new CardPayment();
            default -> throw new IllegalArgumentException("Unknown method: " + type);
        };
    }
}

public class FactoryDemo {
    public static void main(String[] args) {
        PaymentMethod rajesh = PaymentFactory.create("UPI");   // caller names the type
        PaymentMethod priya  = PaymentFactory.create("CARD");
        rajesh.pay(new BigDecimal("5000"));
        priya.pay(new BigDecimal("12000"));
    }
}
